CREATE POLICY brand_files_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='brand-assets');
CREATE POLICY brand_files_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='brand-assets' AND public.is_staff());
CREATE POLICY brand_files_edit ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='brand-assets' AND public.is_staff()) WITH CHECK(bucket_id='brand-assets' AND public.is_staff());
CREATE POLICY brand_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='brand-assets' AND public.is_staff());
CREATE OR REPLACE FUNCTION public.validate_brand() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.title_font NOT IN ('Cairo','Tajawal','Almarai','IBM Plex Sans Arabic','Noto Sans Arabic','Noto Kufi Arabic','Readex Pro','Amiri') OR NEW.body_font NOT IN ('Cairo','Tajawal','Almarai','IBM Plex Sans Arabic','Noto Sans Arabic','Noto Kufi Arabic','Readex Pro','Amiri') THEN RAISE EXCEPTION 'خط غير مدعوم'; END IF; IF NOT (NEW.refaq_logo LIKE '/__l5e/assets-v1/%' OR NEW.refaq_logo ~ '^brand:[a-zA-Z0-9._-]+$') OR NOT (NEW.wathiq_logo LIKE '/__l5e/assets-v1/%' OR NEW.wathiq_logo ~ '^brand:[a-zA-Z0-9._-]+$') THEN RAISE EXCEPTION 'مصدر الشعار غير معتمد'; END IF; RETURN NEW; END; $$;
